from pathlib import Path
import json,hashlib,zipfile,math,html,posixpath
D=Path('dist');O=D/'offline';O.mkdir(exist_ok=True)
def size(n): return f'{n/1024/1024:.1f} MB' if n>=1024*1024 else f'{math.ceil(n/1024)} KB'
def link(file,label,description):
 p=D/file
 return f'<article class="card"><h3>{html.escape(label)}</h3><p>{description}</p><p><a class="button secondary" href="../{file}" download>Download {html.escape(label)} · {size(p.stat().st_size)}</a></p></article>'
readers=json.loads((O/'readers.json').read_text())
reader_cards=''.join(link('offline/'+m['name'],f'Unit {m["unit"]} reader (HTML)',f'{m["chapters"]} chapters. Single file: text, diagrams and worked examples embedded. Open in any modern browser; no installation or internet needed for reading. Includes explained answers and student/answer print options.') for m in readers)
small=''.join(link(f'activities/{slug}/student.pdf',label+' student sheets (PDF)','Printable student activities. Equipment-free options included; teacher answers are in the complete library and activity hub.') for slug,label in [('programming-foundations','Programming foundations'),('programming-next','Programming next steps'),('databases-sql','Databases and SQL'),('network-reasoning','Networks'),('computer-systems','Computer systems')])
small+=link('sql/sql-student-pack.zip','SQL student pack (ZIP)','Database fixtures, exercises and expected-result files. Extract the ZIP; use SQLite-compatible software for queries. Reference solutions are a separate download in the SQL pathway.')
small+=link('revision/student-workbook.md','Revision workbook (Markdown text)','Topic checklists and retrieval prompts. Open with a text editor; use the revision hub or complete library for cumulative quizzes and explained answers.')
zip_path=O/'cs-atar-complete.zip'
def page(zip_size):
 return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline downloads · CS ATAR</title><link rel="stylesheet" href="../style.css?v={hashlib.sha256((D/'style.css').read_bytes()).hexdigest()[:12]}"><style>main{{max-width:1100px;margin:auto}}.download-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}.download-grid h3{{font-size:1.3rem}}@media(max-width:700px){{.download-grid{{grid-template-columns:1fr}}}}@media print{{.download-grid{{display:block}}.card{{break-inside:avoid}}}}</style></head><body><a class="skip" href="#main">Skip to downloads</a><header><a href="../#home">← Textbook home</a><nav aria-label="Resources"><a href="../resources/">Lesson resources</a><a href="../activities/">Activity packs</a></nav></header><main id="main" tabindex="-1"><p class="eyebrow">SAVE AT SCHOOL · LEARN ANYWHERE</p><h1>Keep a copy.<br>Keep learning.</h1><p class="lede">Choose a small unit reader or take the whole library. Download while connected, then open your saved files at home.</p><p>Release: 31 October 2026 · 2026 foundation, revised for 2027 · classroom draft. Saved copies do not update automatically; return here for a newer release. No account required.</p><section><h2>1. Just the reading</h2><p>The smallest complete reading option. Save the HTML file rather than a shortcut to this page. Once saved, switch off your connection and open it from your Downloads folder to check it before leaving school.</p><div class="download-grid">{reader_cards}</div></section><section class="home-offline"><h2>2. The complete resource library</h2><p>All four units, lesson resources, five activity packs, Python examples, SQL databases, revision, teacher planning and printable downloads. Includes public explained answers and teacher copies.</p><p><a class="button" href="cs-atar-complete.zip" download>Download complete library · ZIP · {zip_size}</a></p><ol><li>Download and extract the ZIP fully, keeping its folders together.</li><li>Open <strong>index.html</strong> in your browser. Follow the local menus as usual.</li><li>Open PDFs separately to print; use the chapter print controls for student or answer copies.</li></ol><p>Reading, diagrams, local navigation and bundled downloads work without internet. External websites and official SCSA documents linked online require a connection. Python, Pygame and SQL execution need their own installed tools; the ZIP does not install them. Browser settings may limit saved progress when opening local files. The single-file readers are the simplest reading fallback.</p><p><a href="README.txt" download>Plain-text setup instructions</a> · <a href="manifest.json" download>File sizes and verification hashes (JSON)</a></p></section><section><h2>3. Smaller practice downloads</h2><p>Choose only what your next lesson needs. PDF files open in a PDF reader; ZIP files need extraction; Markdown opens as plain text.</p><div class="download-grid">{small}</div></section><section><h2>Reading and access options</h2><ul><li>Use your browser zoom and text size settings. At narrow widths, tables, code and large diagrams scroll within their own region.</li><li>Use Tab and Shift+Tab to move between controls, Enter to follow links and Space or Enter to open answer sections. A visible focus outline shows your position.</li><li>Diagram text descriptions and full-size links accompany textbook figures. Open the full-size image for dense relationship labels.</li><li>Chapter print buttons offer student copies or explained answers. Your browser can save a PDF; preview the page range before printing.</li></ul><p>For a school-managed device that blocks local scripts, use the self-contained readers for reading and the PDFs for practice. Keep the complete folder for a device where local browsing is permitted.</p></section><footer><p>Independent teaching draft; review continues. <a href="../licence.html">Reuse and attribution</a> · <a href="../#sources">Edition and sources</a></p></footer></main></body></html>'''
(O/'README.txt').write_text('CS ATAR offline library — 31 October 2026\n2026 foundation, revised for 2027. Classroom draft; review continues.\n\nExtract the complete ZIP before use. Open index.html in a modern browser. Keep folders together. No server or account is required for reading. If scripts are blocked by school policy, open offline/unit-1-reader.html (or Units 2–4) and use activity PDFs.\n\nThe four unit readers embed their diagrams and chapter text. They include public explained answers. Reader print buttons offer student/answer copies; use browser Save as PDF.\n\nExternal links and official sources need internet. Python/Pygame and SQLite require suitable installed software. Local-file browser policies may limit progress storage. Downloads do not update automatically.\n\nOriginal content CC BY 4.0, original code MIT; see licence.html and included licence files. All teacher/reference answers are public resources, not secure assessments.\n',encoding='utf8',newline='\n')
# Rebuild after runtime assets are versioned. Include licences and a file-URL adapter.
label='preparing download'
for attempt in range(8):
 (O/'index.html').write_text(page(label),encoding='utf8',newline='\n')
 with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
  for p in sorted(D.rglob('*')):
   if not p.is_file() or p==zip_path or p==O/'manifest.json':continue
   rel=p.relative_to(D).as_posix(); data=p.read_bytes()
   if p.suffix=='.html':
    adapter=posixpath.relpath('offline/file-links.js',posixpath.dirname(rel) or '.')
    text=data.decode('utf8')
    if rel=='offline/index.html':text=text.replace('href="cs-atar-complete.zip" download','href="https://edugenio.github.io/cs-atar-textbook/offline/cs-atar-complete.zip"').replace('Download complete library · ZIP','Download complete library online · ZIP')
    data=text.replace('</body>',f'<script src="{adapter}"></script></body>').encode('utf8')
   z.writestr(rel,data)
  z.writestr('offline/manifest.json',json.dumps({'release':'2026-10-31','note':'Reader verification; complete ZIP hash is available on the online download page.','files':[{'name':m['name'],'bytes':(O/m['name']).stat().st_size,'sha256':hashlib.sha256((O/m['name']).read_bytes()).hexdigest()} for m in readers]},indent=2))
  for name in ['LICENSE-CODE.txt','LICENSE-CONTENT.txt']:
   if not (D/name).exists():z.write(name,name)
 actual=size(zip_path.stat().st_size)
 if actual==label:break
 label=actual
else:raise RuntimeError('ZIP size label did not converge')
files=[O/m['name'] for m in readers]+[zip_path]
(O/'manifest.json').write_text(json.dumps({'release':'2026-10-31','edition':'2026 foundation; 2027 revisions','files':[{'name':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in files]},indent=2)+'\n',encoding='utf8',newline='\n')
print('Offline library:',label,'; four readers and small downloads indexed.')
